def solution(items: list) -> int:
    # Infer pattern: return the maximum subarray sum (Kadane) for the given list
    if not items:
        return 0
    max_ending_here = max_so_far = items[0]
    for x in items[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far
